param([Parameter(Mandatory=$true)][string]$Dir,[Parameter(Mandatory=$true)][string]$ImagePath)
$ErrorActionPreference='Stop';$existing=@(Get-CimInstance Win32_Process -Filter "Name='WINWORD.EXE'"|ForEach-Object{[int]$_.ProcessId});$owned=@();$w=New-Object -ComObject Word.Application;$w.Visible=$false;$w.DisplayAlerts=0
try{$d=$w.Documents.Add();$owned=@(Get-CimInstance Win32_Process -Filter "Name='WINWORD.EXE'"|Where-Object{[int]$_.ProcessId -notin $existing}|ForEach-Object{[int]$_.ProcessId});if(-not $owned.Count){throw 'Word COM PID missing'};$d.Content.Text='Image audit';$range=$d.Range($d.Content.End-1,$d.Content.End-1);[void]$d.InlineShapes.AddPicture($ImagePath,$false,$true,$range);$d.SaveAs2("$Dir\word_image_t8_new.docx",16);$d.Close(0);foreach($name in @('word_image_t8_new.docx','app_image_t8_new.docx')){$d=$w.Documents.Open("$Dir\$name",$false,$true);try{$rows=@();foreach($s in $d.InlineShapes){$rows+=('{0}|{1}|{2}|{3}' -f [int]$s.Type,[math]::Round([double]$s.Width,1),[math]::Round([double]$s.Height,1),[int]$s.Range.ParagraphFormat.Alignment)};Write-Output ("{0}: inlineShapes={1}; {2}" -f $name,$d.InlineShapes.Count,($rows -join '; '))}finally{$d.Close(0)}}
}finally{if($w){$w.Quit();[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($w)};$owned=@($owned+@(Get-CimInstance Win32_Process -Filter "Name='WINWORD.EXE'"|Where-Object{[int]$_.ProcessId -notin $existing}|ForEach-Object{[int]$_.ProcessId})|Select-Object -Unique);foreach($ownedPid in $owned){$p=Get-Process -Id $ownedPid -ErrorAction SilentlyContinue;if($p){$p|Wait-Process -Timeout 3 -ErrorAction SilentlyContinue};if(Get-Process -Id $ownedPid -ErrorAction SilentlyContinue){Stop-Process -Id $ownedPid -Force -ErrorAction SilentlyContinue}}}
